function advance(face: Face, ch: string) {
  const code = ch.charCodeAt(0);
  if (code >= 32 && code < 127) return face.adv[code - 32] / 1000;
  return (face.punct[ch] ?? 620) / 1000;
}

/** Left edge (em) of every glyph in a run, with kerning and tracking. */
function layoutRun(face: Face, chars: string[]) {
  const xs: number[] = [];
  let x = 0;
  chars.forEach((ch, i) => {
    if (i > 0) x += face.kern.get(chars[i - 1] + ch) ?? 0;
    xs.push(x);
    x += advance(face, ch) + face.track;
  });
  return { xs, total: Math.max(0, x - face.track) };
}

/** Line breaks at a measure, then narrowed until the lines balance. */
function breakLines(words: string[][], measure: number) {
  const space = advance(BODY, " ") + BODY.track;
  const widths = words.map((w) => layoutRun(BODY, w).total);
  const wrap = (max: number) => {
    const lines: number[][] = [];
    let line: number[] = [];
    let width = 0;
    widths.forEach((w, i) => {
      const next = line.length ? width + space + w : w;
      if (line.length && next > max) {
        lines.push(line);
        line = [i];
        width = w;
      } else {
        line.push(i);
        width = next;
      }
    });
    if (line.length) lines.push(line);
    return lines;
  };
  const count = wrap(measure).length;
  let lo = Math.max(...widths, 0);
  let hi = measure;
  for (let n = 0; n < 24; n++) {
    const mid = (lo + hi) / 2;
    if (wrap(mid).length > count) lo = mid;
    else hi = mid;
  }
  return wrap(hi);
}

/** Pick the letters of `word` in order, spread as evenly as the sentence allows. */
function findLetters(text: string[], word: string[]) {
  const n = word.length;
  const len = text.length;
  if (!n) return [];
  const cost = (j: number, i: number) => {
    const a = text[i];
    const b = word[j];
    if (a.toLowerCase() !== b.toLowerCase()) return Number.POSITIVE_INFINITY;
    const target = ((j + 0.5) / n) * len;
    return Math.abs(i - target) + (a === b ? 0 : len * 0.25);
  };
  // best[j][i]: cheapest placement of letters 0..j with letter j at index i.
  const best: number[][] = [];
  const from: number[][] = [];
  for (let j = 0; j < n; j++) {
    best.push(new Array<number>(len).fill(Number.POSITIVE_INFINITY));
    from.push(new Array<number>(len).fill(-1));
    let run = Number.POSITIVE_INFINITY;
    let runAt = -1;
    for (let i = 0; i < len; i++) {
      const c = cost(j, i);
      if (j === 0) best[j][i] = c;
      else if (runAt >= 0 && c < Number.POSITIVE_INFINITY) {
        best[j][i] = run + c;
        from[j][i] = runAt;
      }
      if (j > 0 && best[j - 1][i] < run) {
        run = best[j - 1][i];
        runAt = i;
      }
    }
  }
  let end = -1;
  best[n - 1].forEach((v, i) => {
    if (v < Number.POSITIVE_INFINITY && (end < 0 || v < best[n - 1][end]))
      end = i;
  });
  if (end < 0) {
    // Not every letter is in the sentence: match greedily, leave gaps as -1.
    let at = 0;
    return word.map((ch) => {
      for (let i = at; i < len; i++)
        if (text[i].toLowerCase() === ch.toLowerCase()) {
          at = i + 1;
          return i;
        }
      return -1;
    });
  }
  const out = new Array<number>(n).fill(-1);
  for (let j = n - 1, i = end; j >= 0; j--) {
    out[j] = i;
    i = from[j][i];
  }
  return out;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Glyph {
  ch: string;
  x: number;
  line: number;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function HiddenWordBase({
  text = "Small teams make their launch film in code and post it by Friday.",
  word = "ship",
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  stagger = LIFT_STAGGER,
  scale: layerScale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
}: HiddenWordProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const B = Math.min(H * 0.068, W * 0.038);
  const set = useMemo(() => {
    const chars = Array.from(text);
    const words: string[][] = [];
    const starts: number[] = [];
    chars.forEach((ch, i) => {
      if (ch === " ") return;
      if (i === 0 || chars[i - 1] === " ") {
        words.push([]);
        starts.push(i);
      }
      words[words.length - 1].push(ch);
    });
    const lines = breakLines(words, (W * 0.66) / B);
    const space = advance(BODY, " ") + BODY.track;
    const glyphs: (Glyph | null)[] = chars.map(() => null);
    let blockWidth = 0;
    lines.forEach((line, l) => {
      let x = 0;
      line.forEach((wi, k) => {
        if (k > 0) x += space;
        const run = layoutRun(BODY, words[wi]);
        run.xs.forEach((gx, g) => {
          glyphs[starts[wi] + g] = { ch: words[wi][g], x: x + gx, line: l };
        });
        x += run.total;
      });
      blockWidth = Math.max(blockWidth, x);
    });
    return { chars, glyphs, lines: lines.length, blockWidth };
  }, [text, W, B]);

  const target = useMemo(() => Array.from(word), [word]);
  const picks = useMemo(
    () => findLetters(set.chars, target),
    [set.chars, target],
  );
  const display = useMemo(() => layoutRun(DISPLAY, target), [target]);

  // Opening layout: the sentence block centred in frame.
  const lineGap = B * LEADING;
  const blockLeft = W / 2 - (set.blockWidth * B) / 2;
  const firstBase =
    H / 2 - ((set.lines - 1) * lineGap) / 2 + (CAP * B) / 2 - B * 0.04;
  const blockTop = firstBase - CAP * B;
  const blockBottom = firstBase + (set.lines - 1) * lineGap + DESC * B;
  const blockMid = (blockTop + blockBottom) / 2;

  // Poster layout: the display word over the sentence, now a small caption.
  const F = Math.min(H * 0.42, (W * 0.6) / Math.max(0.1, display.total));
  const ghostH = (blockBottom - blockTop) * GHOST_SCALE;
  const gap = H * 0.085;
  // The found word is lowercase: centre it on its x-height, not the caps.
  const topE = (CAP + SERIF_X) / 2;
  const groupH = topE * F + DESC * F + gap + ghostH;
  const displayBase = H * 0.5 - groupH / 2 + topE * F;
  const ghostMid = displayBase + DESC * F + gap + ghostH / 2;
  const displayLeft = W / 2 - (display.total * F) / 2;

  const move = interpolate(t, [MOVE_AT, MOVE_AT + MOVE], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const placeAt = (m: number) => {
    const scale = 1 + (GHOST_SCALE - 1) * m;
    const midY = blockMid + (ghostMid - blockMid) * m;
    const place = (x: number, y: number) => ({
      x: W / 2 + (x - W / 2) * scale,
      y: midY + (y - blockMid) * scale,
    });
    return { scale, midY, place };
  };
  // Layout rounds a baseline to whole pixels, so letters carried by `top`
  // and `fontSize` click along pixel by pixel. The sentence is laid out where
  // it rests, the opening for the first half of the move and the caption for
  // the second, and the move between them is a transform on a wrapper. The
  // switch lands on the fastest frames, and each rest is laid out as before.
  const now = placeAt(move);
  const anchor = placeAt(move < 0.5 ? 0 : 1);
  const settled = (dx: number, dy: number, k: number) =>
    Math.abs(dx) < 1e-3 && Math.abs(dy) < 1e-3 && Math.abs(k - 1) < 1e-6;

  const picked = new Map<number, number>();
  picks.forEach((i, j) => {
    if (i >= 0) picked.set(i, j);
  });
  const lastLand = LIFT_AT + Math.max(0, target.length - 1) * stagger + FLIGHT;
  const settle = interpolate(
    t,
    [lastLand + SETTLE_GAP, lastLand + SETTLE_GAP + SETTLE],
    [0, 1],
    { ...CLAMP, easing: EASE_IO },
  );
  const dim = interpolate(t, [DIM_AT, DIM_AT + DIM], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const restColor = interpolateColors(
    move,
    [0, 1],
    [interpolateColors(dim, [0, 1], [fg, c.dim]), c.ghost],
  );

  const sentence: ReactNode[] = [];
  const marks: ReactNode[] = [];
  const flyers: ReactNode[] = [];

  set.glyphs.forEach((g, i) => {
    if (!g) return;
    const enter = interpolate(
      t,
      [g.line * LINE_STAGGER, g.line * LINE_STAGGER + ENTER],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const homeX = blockLeft + g.x * B;
    const lineY = firstBase + g.line * lineGap;
    const j = picked.get(i);
    if (j === undefined) {
      const size = B * anchor.scale;
      const p = anchor.place(homeX, lineY);
      const rise = (1 - enter) * B * 0.45 * anchor.scale;
      sentence.push(
        <span
          key={i}
          style={{
            position: "absolute",
            left: p.x,
            top: p.y - baseOf(BODY) * size,
            fontSize: size,
            color: restColor,
            opacity: enter,
            // Kept at 0 once the letter is in: the lean rides on it.
            transform: `translateY(${rise > 1e-3 ? rise : 0}px)${glide(midway(enter))}`,
          }}
        >
          {g.ch}
        </span>,
      );
      return;
    }

    const lit = interpolate(
      t,
      [LIGHT_AT + j * LIGHT_STAGGER, LIGHT_AT + j * LIGHT_STAGGER + LIGHT],
      [0, 1],
      { ...CLAMP, easing: EASE_OUT },
    );
    const liftAt = LIFT_AT + j * stagger;
    const p = interpolate(t, [liftAt, liftAt + FLIGHT], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });

    // The empty slot the letter leaves behind gets a short accent rule.
    const hole = interpolate(p, [0.15, 0.55], [0, 1], CLAMP);
    if (hole > 0) {
      const size = B * anchor.scale;
      const w = advance(BODY, g.ch) * size;
      const at = anchor.place(homeX, lineY);
      marks.push(
        <div
          key={`m${i}`}
          style={{
            position: "absolute",
            left: at.x + w * 0.12,
            top: at.y + size * 0.16,
            width: w * 0.76,
            height: Math.max(2, size * 0.07),
            background: accent,
            opacity: hole,
            transform: `scaleX(${0.4 + 0.6 * hole})`,
          }}
        />,
      );
    }

    const toCh = target[j];
    const to = {
      x: displayLeft + (display.xs[j] + advance(DISPLAY, toCh) / 2) * F,
      y: displayBase,
    };
    const flight = (p: number, enter: number, move: number) => {
      const { scale, place } = placeAt(move);
      const size = B * scale;
      const homeY = lineY + (1 - enter) * B * 0.45;
      const from = place(homeX + (advance(BODY, g.ch) * B) / 2, homeY);
      // Lift straight up out of the line, cross over, rise into the slot from below.
      const c1y = from.y - (g.line + 1.6) * lineGap * scale;
      const c2y = to.y + F * 0.55;
      const u = 1 - p;
      const x =
        (u * u * u + 3 * u * u * p) * from.x +
        (3 * u * p * p + p * p * p) * to.x;
      const y =
        u * u * u * from.y +
        3 * u * u * p * c1y +
        3 * u * p * p * c2y +
        p * p * p * to.y;
      return { x, y, fontSize: size * (F / size) ** p };
    };
    // The same move for the letter in flight: laid out where it rests, in the
    // sentence for the first half and in the word for the second, and carried
    // by a transform from there.
    const { x, y, fontSize } = flight(p, enter, move);
    const rest = p < 0.5 ? flight(0, 1, 0) : flight(1, 1, 1);
    const flying = midway(p) || midway(enter) || midway(move);
    const mix = interpolate(p, [0.15, 0.55], [0, 1], CLAMP);
    const color = interpolateColors(
      settle,
      [0, 1],
      [interpolateColors(lit, [0, 1], [restColor, accent]), fg],
    );
    const layer = (key: string, ch: string, face: Face, o: number) => {
      if (o <= 0) return null;
      const left = x - (advance(face, ch) * fontSize) / 2;
      const top = y - baseOf(face) * fontSize;
      const restLeft = rest.x - (advance(face, ch) * rest.fontSize) / 2;
      const restTop = rest.y - baseOf(face) * rest.fontSize;
      const k = fontSize / rest.fontSize;
      return (
        <span
          key={key}
          style={{
            position: "absolute",
            left: restLeft,
            top: restTop,
            fontSize: rest.fontSize,
            // At rest the transform stays, as an identity: the lean rides on it.
            transform: settled(left - restLeft, top - restTop, k)
              ? `translate(0px, 0px) scale(1)${glide(false)}`
              : `translate(${left - restLeft}px, ${top - restTop}px) scale(${k})${glide(flying)}`,
            transformOrigin: "0 0",
            fontFamily: face === DISPLAY ? serif : fontFamily,
            fontStyle: face === DISPLAY ? "italic" : "normal",
            letterSpacing: 0,
            color,
            opacity: o * enter,
          }}
        >
          {ch}
        </span>
      );
    };
    flyers.push(layer(`a${i}`, g.ch, BODY, 1 - mix));
    flyers.push(layer(`b${i}`, toCh, DISPLAY, mix));
  });

  // Letters of the word that the sentence does not contain arrive on their own.
  target.forEach((ch, j) => {
    if (picks[j] >= 0) return;
    const at = LIFT_AT + j * stagger + FLIGHT * 0.5;
    const v = interpolate(t, [at, at + FLIGHT * 0.5], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    if (v <= 0) return;
    flyers.push(
      <span
        key={`n${j}`}
        style={{
          position: "absolute",
          left: displayLeft + display.xs[j] * F,
          top: displayBase - baseOf(DISPLAY) * F,
          transform: `translateY(${v < 1 ? (1 - v) * F * 0.12 : 0}px)${glide(midway(v))}`,
          fontSize: F,
          fontFamily: serif,
          fontStyle: "italic",
          color: interpolateColors(settle, [0, 1], [accent, fg]),
          opacity: v,
        }}
      >
        {ch}
      </span>,
    );
  });

  // The bloom drifts a few percent left and up over the shot.
  const drift = interpolate(t, [0, lastLand + SETTLE_GAP + SETTLE], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const ground = `radial-gradient(118% 76% at ${(72 - 8 * drift).toFixed(2)}% ${(104 - 4 * drift).toFixed(2)}%, ${c.mist[0]} 0%, ${c.mist[1]} 22%, ${c.mist[2]} 48%, ${c.mist[3]} 72%, transparent 100%)`;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {background === undefined ? (
        <div style={{ position: "absolute", inset: 0, background: ground }} />
      ) : null}
      <ScaleLayer scale={layerScale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            fontFamily,
            fontWeight: 400,
            lineHeight: LINE,
            fontKerning: "none",
            whiteSpace: "pre",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              // An identity at either rest, so the mark the lean rides on
              // stays on: dropping it would snap text resting off the grid.
              transform:
                move > 0 && move < 1
                  ? `translateY(${now.midY - anchor.midY}px) scale(${now.scale / anchor.scale})${glide(midway(move))}`
                  : `translateY(0px) scale(1)${glide(false)}`,
              transformOrigin: `${W / 2}px ${anchor.midY}px`,
            }}
          >
            {sentence}
            {marks}
          </div>
          {flyers}
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}

