const ELEMENT_PROP_KEYS = new Set(["theme","text","word","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Small teams make their launch film in code and post it by Friday.",
  word: "ship",
  stagger: 6,
  accent: "#3B5BFD",
